 47→## 1. `app/server.py`: `GET /api/review/runs`
 48→
 49→A read-only list of the run folders the console can open by id, newest first, at most 100.
 50→
 51→**1a.** Directly after the `_DISPUTE_ID_RE = ...` line, add:
 52→
 53→```python
 54→#: W35: the console's Recent runs list shows at most this many runs, newest first.
 55→RECENT_RUNS_LIMIT = 100
 56→```
 57→
 58→**1b.** Directly after `_review_overrides` (after its `return {"approved_count": ...}` line and before
 59→the `# --- filing builder` comment), add these two functions:
 60→
 61→```python
 62→def _recent_run_entry(run_id: str, case: Dict[str, Any], run_dir: Path) -> Optional[Dict[str, Any]]:
 63→    """One Recent runs row, or None when the case file lacks a field the console relies on.
 64→
 65→    The case must name this folder as its run_id (the console opens the folder by that id
 66→    and asks for its prompts by the case's run_id), carry a dispute id, and record an
 67→    outcome. Category and generated_at are shown when they are strings, else as "".
 68→    """
 69→    if case.get("run_id") != run_id:
 70→        return None
 71→    dispute_id = case.get("dispute_id")
 72→    if not isinstance(dispute_id, str) or not dispute_id:
 73→        return None
 74→    resolution = case.get("resolution")
 75→    if not isinstance(resolution, dict):
 76→        return None
 77→    outcome = resolution.get("outcome")
 78→    if not isinstance(outcome, str) or not outcome:
 79→        return None
 80→    category = case.get("category")
 81→    generated_at = case.get("generated_at")
 82→    return {
 83→        "run_id": run_id,
 84→        "dispute_id": dispute_id,
 85→        "category": category if isinstance(category, str) else "",
 86→        "outcome": outcome,
 87→        "generated_at": generated_at if isinstance(generated_at, str) else "",
 88→        "has_human_decision": load_decision(run_dir) is not None,
 89→    }
 90→
 91→
 92→def _recent_runs(out_dir: Path) -> List[Dict[str, Any]]:
 93→    """W35: the newest run folders the console can open by id, newest first. Read-only.
 94→
 95→    A folder is listed only when GET /api/review/<run_id>/case would open it: its name
 96→    passes the run-id rule, it resolves inside out_dir and is not out_dir itself (a
 97→    symlink that escapes is skipped), and it holds a case file that is a JSON object
 98→    with the fields the row needs. Anything else, a plain file included, is skipped,
 99→    never a 500. Ties on generated_at go to the larger run id; the list is cut at
100→    RECENT_RUNS_LIMIT.
101→    """
102→    try:
103→        root = out_dir.resolve()
104→        children = list(out_dir.iterdir())
105→    except OSError:
106→        return []
107→    found: List[Tuple[Any, str, Dict[str, Any]]] = []
108→    for child in children:
109→        run_id = child.name
110→        if not _RUN_ID_RE.fullmatch(run_id) or run_id in (".", ".."):
111→            continue
112→        try:
113→            run_dir = child.resolve()
114→            if run_dir == root or not run_dir.is_relative_to(root):
115→                continue
116→        except (OSError, RuntimeError):
117→            continue
118→        case = _read_json_object(run_dir / CASE_FILE_NAME)
119→        if case is None:
120→            continue
121→        entry = _recent_run_entry(run_id, case, run_dir)
122→        if entry is None:
123→            continue
124→        found.append((_timestamp_key(case.get("generated_at")), run_id, entry))
125→    found.sort(key=lambda item: (item[0], item[1]), reverse=True)
126→    return [entry for _key, _run_id, entry in found[:RECENT_RUNS_LIMIT]]
127→```
