242→**4e.** Replace the whole function `handleFile(file)` with these four functions (the read, the
243→generation guard and both JSON messages are unchanged; the reset and the failure display become
244→shared, and the picked folder's files attach only after the case loaded):
245→
246→```js
247→  // A local load is a user action: it wins over a pending deep link, drops every pending
248→  // server open and any late /prompts reply, and clears the server selection. Returns the
249→  // generation the local read must still own when it settles.
250→  function beginLocalLoad() {
251→    state.userActionSeen = true;
252→    state.openRun = null;
253→    state.currentQueueRun = null;
254→    state.currentList = null;
255→    invalidatePendingOpens();
256→    state.promptsGeneration += 1;
257→    applyQueueSelection();
258→    if (decisionSection) {
259→      decisionSection.hidden = true;
260→    }
261→    state.payloadFiles = {};
262→    setPayloadStatus("Payload files are not attached.", "idle");
263→    return state.openGeneration;
264→  }
265→
266→  function showLoadFailure(message) {
267→    state.openRun = null;
268→    if (decisionSection) {
269→      decisionSection.hidden = true;
270→    }
271→    workspace.hidden = true;
272→    clear(metadataList);
273→    clear(grievanceContent);
274→    clear(evidenceContent);
275→    if (promptsContent) {
276→      clear(promptsContent);
277→    }
278→    clear(claimsContent);
279→    clear(policyContent);
280→    clear(resolutionContent);
281→    clear(eventsContent);
282→    setStatus(message, "error");
283→  }
284→
285→  function handleFile(file, label, runFiles) {
286→    if (!file) {
287→      return;
288→    }
289→
290→    var readGeneration = beginLocalLoad();
291→    var name = label || file.name;
292→    setStatus("Reading " + name + "…", "loading");
293→    file.text().then(function (text) {
294→      if (readGeneration !== state.openGeneration) {
295→        return;
296→      }
297→      var parsed;
298→      try {
299→        parsed = JSON.parse(text);
300→      } catch (error) {
301→        throw new Error("The selected file is not valid JSON.");
302→      }
303→      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
304→        throw new Error("The selected JSON must contain one case-file object.");
305→      }
306→      renderCase(name, parsed);
307→      if (runFiles) {
308→        attachRunFiles(runFiles);
309→      }
310→    }).catch(function (error) {
311→      if (readGeneration !== state.openGeneration) {
312→        return;
313→      }
314→      showLoadFailure(error.message);
315→    });
316→  }
317→
318→  // W35: one picker. The picked run folder's own case_file.json loads through handleFile and
319→  // every file in the folder is attached for the event payloads, in one action.
320→  function handleRunFolder(files) {
321→    var list = Array.prototype.slice.call(files || []);
322→    if (list.length === 0) {
323→      return;
324→    }
325→    var picked = pickedRunFolder(list);
326→    if (!picked.file) {
327→      beginLocalLoad();
328→      showLoadFailure(picked.error);
329→      return;
330→    }
331→    handleFile(picked.file, picked.label, list);
332→  }
333→```
